/// Common interface for TPC-C drivers (one impl per Postgres client).
///
/// Mix selector / harness in `tpcc_small.dart` calls these methods
/// with parameters generated by a seeded RNG so both drivers traverse
/// identical decision paths.
library;

abstract class TpccDriver {
  /// Open connections, prepare pool, etc. Idempotent.
  Future<void> setup();

  Future<void> newOrder(NewOrderParams p);
  Future<void> payment(PaymentParams p);
  Future<void> orderStatus(OrderStatusParams p);
  Future<void> delivery(DeliveryParams p);
  Future<void> stockLevel(StockLevelParams p);

  Future<void> close();
}

class NewOrderLineItem {
  final int iId;
  final int supplyWId;
  final int quantity;
  const NewOrderLineItem(this.iId, this.supplyWId, this.quantity);
}

class NewOrderParams {
  final int wId;
  final int dId;
  final int cId;
  final List<NewOrderLineItem> lines;
  const NewOrderParams(this.wId, this.dId, this.cId, this.lines);
}

class PaymentParams {
  final int wId;
  final int dId;
  final int cId;
  final double amount;
  const PaymentParams(this.wId, this.dId, this.cId, this.amount);
}

class OrderStatusParams {
  final int wId;
  final int dId;
  final int cId;
  const OrderStatusParams(this.wId, this.dId, this.cId);
}

class DeliveryParams {
  final int wId;
  final int carrierId;
  const DeliveryParams(this.wId, this.carrierId);
}

class StockLevelParams {
  final int wId;
  final int dId;
  final int threshold;
  const StockLevelParams(this.wId, this.dId, this.threshold);
}
